class LibraryMember{protected String memberId;protected int borrowLimit;protected int booksBorrowed;public LibraryMember(String id,int limit){if(id==null||id.trim().length()<4)throw new IllegalArgumentException("Invalid member ID");if(limit<=0)throw new IllegalArgumentException("Borrow limit must be positive");memberId=id;borrowLimit=limit;booksBorrowed=0;}public void borrowBook(){if(booksBorrowed<borrowLimit)booksBorrowed++;}public int getBooksBorrowed(){return booksBorrowed;}public void displayInfo(){System.out.println("General Member | Books Borrowed: "+booksBorrowed);}}
class StudentMember extends LibraryMember{private String course;public StudentMember(String id,int l,String c){super(id,l);course=c;}public String getCourse(){return course;}public void displayInfo(){System.out.println("Student Member | Course: "+course+" | Books Borrowed: "+getBooksBorrowed());}}
public class LibraryEnrollment{static String enrollBatch(String[] ids,int l){int ok=0,no=0;for(String id:ids)try{new LibraryMember(id,l);ok++;}catch(IllegalArgumentException e){no++;}return "Enrolled: "+ok+" | Rejected: "+no;}public static void main(String[] args){try{new LibraryMember("LB1",3);}catch(IllegalArgumentException e){System.out.println("construction rejected");}StudentMember s=new StudentMember("STU10",3,"CSE");s.borrowBook();s.borrowBook();System.out.println(s.getBooksBorrowed());String[] ids={"STU1","LB1","STU2"," ","STU3"};System.out.println(enrollBatch(ids,3));}}